(function(){'use strict';window.WBSiteHealthUI=function(ctx){const{esc:e,icon,toast,heading,badge}=ctx;let state=null,busy=false,error='',selected='health';const date=v=>!v?'还未检查':!Number.isFinite(Date.parse(v))?'日期未确认':new Intl.DateTimeFormat('zh-CN',{timeZone:'America/Los_Angeles',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v));async function request(url,options){const r=await fetch(url,options),v=await r.json();if(!r.ok)throw Error(v.error||'站点检查未完成');return v;}async function init(){try{state=await request('/api/site-health');}catch(err){error=err.message;}}function summary(){return`<div class="site-inline"><div><span class="tiny-dot"></span><strong>Packrivo</strong><span>${state?.status==='ok'?'最近一次访问正常':state?.status==='attention'?'有响应需要查看':state?.status==='unknown'?'上次检查未完成':'尚未检查'}</span></div><a href="#business" class="text-button">查看网站状态 ${icon('arrow-right')}</a></div>`;}function detailsView(){return`<section class="panel website-health"><div class="section-heading"><div><span class="section-kicker">网站公开状态</span><h2>Packrivo</h2><p>先确认网站是否可访问，再处理值得关注的变化。</p></div><button class="primary-button" data-action="site-health-check" ${busy?'disabled':''}>${icon('radar')}${busy?'正在检查…':'检查公开状态'}</button></div><div class="site-status-row">${badge(state?.status==='ok'?'最近请求成功':state?.status==='attention'?'响应需查看':state?.status==='unknown'?'检查未完成':'尚未检查',state?.status==='ok'?'teal':state?.status==='attention'?'amber':'neutral')}<span>最后检查：${e(date(state?.checkedAt))}</span><a href="https://packrivo.com/" target="_blank" rel="noopener noreferrer">打开网站 ${icon('external-link')}</a></div>${error?`<p role="alert" class="inline-error">${e(error)}</p>`:''}<div class="health-checks">${(state?.checks||[]).map(c=>`<article><div><strong>${e(c.label)}</strong>${badge(c.status==='ok'?'请求成功':c.status==='error'?'未完成':'需查看',c.status==='ok'?'teal':c.status==='error'?'neutral':'amber')}</div><p>${c.statusCode?'HTTP '+Number(c.statusCode):'未取得响应'}${Number.isFinite(c.durationMs)?' · '+Number(c.durationMs)+' ms':''}</p><small>${e(c.message)}${c.error?' · '+e(c.error):''}</small>${c.certificate?.httpsValidated?'<small>HTTPS 证书校验已通过</small>':''}${c.certificate?.validTo?`<small>证书有效至 ${e(date(c.certificate.validTo))}</small>`:''}<code>${e(c.finalUrl||c.url)}</code></article>`).join('')||'<div class="empty-inline">手动检查后，会在这里保留本次结果与检查时间。</div>'}</div><p class="quiet-note">${icon('info')}${e(state?.notice||'只检查固定公开页面，不访问后台或提交表单；一次请求成功不代表所有业务功能正常。')}</p></section><section class="section-space">${heading('网站数据入口','接入真实数据后，再看访问、搜索和询盘的变化。')}<div class="website-metrics">${Object.values(state?.analytics||{a:{label:'Google搜索表现',description:'需Search Console本站授权'},b:{label:'访问与来源',description:'需GA4采集及本站授权'},c:{label:'真实询盘',description:'需真实表单或业务系统汇总'}}).map(c=>`<article class="panel"><span>${e(c.label)}</span><strong class="metric-unavailable">未接入</strong><p>${e(c.description)}</p><small>没有数据时，不显示为零。</small></article>`).join('')}</div></section>${state?.history?.length?`<section class="panel section-space">${heading('最近检查','只保留真实检查记录，不自动生成历史曲线。')}<div class="health-history">${state.history.slice(0,7).map(h=>`<div><span>${e(date(h.checkedAt))}</span><span>${h.status==='ok'?'请求成功':h.status==='unknown'?'检查未完成':'响应需查看'}</span><span>${Number.isFinite(h.durationMs)?h.durationMs+' ms':'—'}</span></div>`).join('')}</div></section>`:''}`;}function view(){return (window.WBVisuals?window.WBVisuals.business(state,selected,busy):'')+'<details class="visual-records"><summary>查看入口请求、数据接入与检查记录</summary>'+detailsView()+'</details>';}async function handle(action,el){if(action==='site-map-select'){if(['health','search','visits','inquiries'].includes(el?.dataset?.value)){selected=el.dataset.value;ctx.render();if(typeof document!=='undefined')document.querySelector('[data-action="site-map-select"][data-value="'+selected+'"]')?.focus({preventScroll:true});}return true;}if(action!=='site-health-check')return false;if(busy)return true;busy=true;error='';ctx.render();try{state=await request('/api/site-health/check',{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Action':'manual'},body:'{}'});toast(state.status==='ok'?'已保存这次公开检查结果':'已保留检查结果，请查看未完成或需关注的项目');}catch(err){error=err.message;toast(error);}finally{busy=false;ctx.render();}return true;}return{init,view,summary,handle,isBusy:()=>busy};};})();
